/**
 * Browser UI preview only (see src/preview/README.md): simulates the camera
 * session so the recorder UI, HUD and the whole record -> upload -> analysis
 * flow can be exercised in a browser. Recording always yields a simulated
 * 2:30 round; frames are generated by video-frame-extractor.web.ts.
 */

import { useCallback, useMemo, useState } from 'react';
import type { CapturePlan, FpsPreference } from './capture-plan';
import { createTelemetryStore } from './capture-telemetry';
import type { SampledFrame } from './frame-processor';

export type LiveCaptureState = 'idle' | 'recording' | 'finishing';

export interface LiveCaptureResult {
  videoUri: string;
  durationMs: number;
  plan: CapturePlan;
  liveSampled: boolean;
  stats: { kept: number; pruned: number; failed: number };
}

export interface LiveCaptureOptions {
  maxDurationMs: number;
  maxFrames: number;
  enableAudio: boolean;
  fpsPreference: FpsPreference;
  onFrame: (frame: SampledFrame) => void;
  uploadPressure: () => number;
  onAutoStop?: () => void;
  onInterrupted?: (reason: string) => void;
}

export const SIMULATED_ROUND_MS = 150_000;

export function useLiveCapture(options: LiveCaptureOptions) {
  const plan = useMemo<CapturePlan>(() => ({ fps: options.fpsPreference === '30' ? 30 : 60, liveSampling: false }), [options.fpsPreference]);
  const telemetry = useMemo(() => createTelemetryStore(), []);
  const [state, setState] = useState<LiveCaptureState>('idle');

  telemetry.set({ plan, configuredFps: plan.fps });

  const start = useCallback(async () => {
    telemetry.set({ recordingStartedAt: Date.now(), keptFrames: 0, prunedFrames: 0, failedFrames: 0, warning: null });
    setState('recording');
  }, [telemetry]);

  const stop = useCallback(async (): Promise<LiveCaptureResult | null> => {
    setState('finishing');
    await new Promise((resolve) => setTimeout(resolve, 300));
    telemetry.set({ recordingStartedAt: 0 });
    setState('idle');
    return {
      videoUri: 'preview://recording.mp4',
      durationMs: Math.min(SIMULATED_ROUND_MS, options.maxDurationMs),
      plan,
      liveSampled: false,
      stats: { kept: 0, pruned: 0, failed: 0 },
    };
  }, [telemetry, plan, options.maxDurationMs]);

  const cancel = useCallback(() => {
    telemetry.set({ recordingStartedAt: 0 });
    setState('idle');
  }, [telemetry]);

  return {
    device: { id: 'preview-back-camera', position: 'back' as const },
    plan,
    probing: false,
    outputs: [],
    constraints: [],
    telemetry,
    state,
    start,
    stop,
    cancel,
    onSessionConfigSelected: () => undefined,
    onInterruptionStarted: () => undefined,
  };
}
